/*  00-create-adventureworkslt.sql

    AdventureWorksLT in one run: the SalesLT schema, its ten tables and all their rows.
    Every demo in this repository runs against what this script creates.

    Where it runs: SQL Server 2016 or later (any edition, local or Docker), Azure SQL Database,
    Azure SQL Managed Instance and SQL database in Microsoft Fabric.

    How to run it:
      1. Create an empty database, for example AdventureWorksLT.
         SQL Server:  CREATE DATABASE AdventureWorksLT;
         Azure SQL and Fabric: create it in the portal.
      2. Connect to that database (not to master) and run this whole file once.
         VS Code with the MSSQL extension: open the file, pick the connection, Run (Ctrl+Shift+E).
      3. The last result set checks the row counts. Every line must say OK.

    It is one batch: no GO separators, so it also runs in web query editors.
    It is all or nothing: one transaction, rolled back on any error.
    It can run again: it drops and recreates the SalesLT tables, nothing else.

    Same data as the official AdventureWorksLT sample, read from AdventureWorksLT2022.bak
    (github.com/microsoft/sql-server-samples, MIT License, Copyright (c) Microsoft Corporation).
    Differences from the official database, none of which the demos use:
      - Product.ThumbNailPhoto and ProductModel.CatalogDescription are NULL.
      - Alias types (dbo.Name, dbo.Phone, ...) are replaced by their base types.
      - No views, functions, sequence or nonclustered indexes, and no dbo.BuildVersion or dbo.ErrorLog.
    Known quirks of the sample, kept on purpose:
      - SalesOrderHeader.SubTotal is not the sum of SalesOrderDetail.LineTotal.
      - The Arabic, Hebrew, Thai and Chinese product descriptions are question marks.
*/

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @db sysname = DB_NAME();
IF @db IN (N'master', N'model', N'msdb', N'tempdb')
BEGIN
    RAISERROR (N'Connect to an empty user database first (for example AdventureWorksLT), not to %s.', 16, 1, @db) WITH NOWAIT;
    RETURN;
END;

BEGIN TRANSACTION;

IF SCHEMA_ID(N'SalesLT') IS NULL
    EXEC (N'CREATE SCHEMA SalesLT;');

/* Re-runs: drop what an earlier run (or the official sample) left behind */
DROP VIEW IF EXISTS SalesLT.vProductAndDescription;
DROP VIEW IF EXISTS SalesLT.vProductModelCatalogDescription;
DROP VIEW IF EXISTS SalesLT.vGetAllCategories;
DROP TABLE IF EXISTS SalesLT.SalesOrderDetail;
DROP TABLE IF EXISTS SalesLT.SalesOrderHeader;
DROP TABLE IF EXISTS SalesLT.CustomerAddress;
DROP TABLE IF EXISTS SalesLT.ProductModelProductDescription;
DROP TABLE IF EXISTS SalesLT.Product;
DROP TABLE IF EXISTS SalesLT.ProductDescription;
DROP TABLE IF EXISTS SalesLT.ProductModel;
DROP TABLE IF EXISTS SalesLT.ProductCategory;
DROP TABLE IF EXISTS SalesLT.Customer;
DROP TABLE IF EXISTS SalesLT.Address;

/* Tables */
CREATE TABLE SalesLT.Address (
    AddressID       int IDENTITY(1, 1) NOT NULL,
    AddressLine1    nvarchar(60)     NOT NULL,
    AddressLine2    nvarchar(60)     NULL,
    City            nvarchar(30)     NOT NULL,
    StateProvince   nvarchar(50)     NOT NULL,
    CountryRegion   nvarchar(50)     NOT NULL,
    PostalCode      nvarchar(15)     NOT NULL,
    rowguid         uniqueidentifier NOT NULL CONSTRAINT DF_Address_rowguid DEFAULT (NEWID()),
    ModifiedDate    datetime         NOT NULL CONSTRAINT DF_Address_ModifiedDate DEFAULT (GETDATE()),
    CONSTRAINT PK_Address_AddressID PRIMARY KEY CLUSTERED (AddressID)
);

CREATE TABLE SalesLT.Customer (
    CustomerID      int IDENTITY(1, 1) NOT NULL,
    NameStyle       bit              NOT NULL CONSTRAINT DF_Customer_NameStyle DEFAULT (0),
    Title           nvarchar(8)      NULL,
    FirstName       nvarchar(50)     NOT NULL,
    MiddleName      nvarchar(50)     NULL,
    LastName        nvarchar(50)     NOT NULL,
    Suffix          nvarchar(10)     NULL,
    CompanyName     nvarchar(128)    NULL,
    SalesPerson     nvarchar(256)    NULL,
    EmailAddress    nvarchar(50)     NULL,
    Phone           nvarchar(25)     NULL,
    PasswordHash    varchar(128)     NOT NULL,
    PasswordSalt    varchar(10)      NOT NULL,
    rowguid         uniqueidentifier NOT NULL CONSTRAINT DF_Customer_rowguid DEFAULT (NEWID()),
    ModifiedDate    datetime         NOT NULL CONSTRAINT DF_Customer_ModifiedDate DEFAULT (GETDATE()),
    CONSTRAINT PK_Customer_CustomerID PRIMARY KEY CLUSTERED (CustomerID)
);

CREATE TABLE SalesLT.CustomerAddress (
    CustomerID      int              NOT NULL,
    AddressID       int              NOT NULL,
    AddressType     nvarchar(50)     NOT NULL,
    rowguid         uniqueidentifier NOT NULL CONSTRAINT DF_CustomerAddress_rowguid DEFAULT (NEWID()),
    ModifiedDate    datetime         NOT NULL CONSTRAINT DF_CustomerAddress_ModifiedDate DEFAULT (GETDATE()),
    CONSTRAINT PK_CustomerAddress_CustomerID_AddressID PRIMARY KEY CLUSTERED (CustomerID, AddressID),
    CONSTRAINT FK_CustomerAddress_Customer_CustomerID FOREIGN KEY (CustomerID) REFERENCES SalesLT.Customer (CustomerID),
    CONSTRAINT FK_CustomerAddress_Address_AddressID FOREIGN KEY (AddressID) REFERENCES SalesLT.Address (AddressID)
);

CREATE TABLE SalesLT.ProductCategory (
    ProductCategoryID       int IDENTITY(1, 1) NOT NULL,
    ParentProductCategoryID int              NULL,
    Name                    nvarchar(50)     NOT NULL,
    rowguid                 uniqueidentifier NOT NULL CONSTRAINT DF_ProductCategory_rowguid DEFAULT (NEWID()),
    ModifiedDate            datetime         NOT NULL CONSTRAINT DF_ProductCategory_ModifiedDate DEFAULT (GETDATE()),
    CONSTRAINT PK_ProductCategory_ProductCategoryID PRIMARY KEY CLUSTERED (ProductCategoryID),
    CONSTRAINT AK_ProductCategory_Name UNIQUE (Name),
    CONSTRAINT FK_ProductCategory_ProductCategory_ParentProductCategoryID_ProductCategoryID
        FOREIGN KEY (ParentProductCategoryID) REFERENCES SalesLT.ProductCategory (ProductCategoryID)
);

CREATE TABLE SalesLT.ProductModel (
    ProductModelID      int IDENTITY(1, 1) NOT NULL,
    Name                nvarchar(50)     NOT NULL,
    CatalogDescription  xml              NULL,
    rowguid             uniqueidentifier NOT NULL CONSTRAINT DF_ProductModel_rowguid DEFAULT (NEWID()),
    ModifiedDate        datetime         NOT NULL CONSTRAINT DF_ProductModel_ModifiedDate DEFAULT (GETDATE()),
    CONSTRAINT PK_ProductModel_ProductModelID PRIMARY KEY CLUSTERED (ProductModelID),
    CONSTRAINT AK_ProductModel_Name UNIQUE (Name)
);

CREATE TABLE SalesLT.ProductDescription (
    ProductDescriptionID int IDENTITY(1, 1) NOT NULL,
    Description          nvarchar(400)    NOT NULL,
    rowguid              uniqueidentifier NOT NULL CONSTRAINT DF_ProductDescription_rowguid DEFAULT (NEWID()),
    ModifiedDate         datetime         NOT NULL CONSTRAINT DF_ProductDescription_ModifiedDate DEFAULT (GETDATE()),
    CONSTRAINT PK_ProductDescription_ProductDescriptionID PRIMARY KEY CLUSTERED (ProductDescriptionID)
);

CREATE TABLE SalesLT.ProductModelProductDescription (
    ProductModelID       int              NOT NULL,
    ProductDescriptionID int              NOT NULL,
    Culture              nchar(6)         NOT NULL,
    rowguid              uniqueidentifier NOT NULL CONSTRAINT DF_ProductModelProductDescription_rowguid DEFAULT (NEWID()),
    ModifiedDate         datetime         NOT NULL CONSTRAINT DF_ProductModelProductDescription_ModifiedDate DEFAULT (GETDATE()),
    CONSTRAINT PK_ProductModelProductDescription_ProductModelID_ProductDescriptionID_Culture
        PRIMARY KEY CLUSTERED (ProductModelID, ProductDescriptionID, Culture),
    CONSTRAINT FK_ProductModelProductDescription_ProductModel_ProductModelID
        FOREIGN KEY (ProductModelID) REFERENCES SalesLT.ProductModel (ProductModelID),
    CONSTRAINT FK_ProductModelProductDescription_ProductDescription_ProductDescriptionID
        FOREIGN KEY (ProductDescriptionID) REFERENCES SalesLT.ProductDescription (ProductDescriptionID)
);

CREATE TABLE SalesLT.Product (
    ProductID              int IDENTITY(1, 1) NOT NULL,
    Name                   nvarchar(50)     NOT NULL,
    ProductNumber          nvarchar(25)     NOT NULL,
    Color                  nvarchar(15)     NULL,
    StandardCost           money            NOT NULL,
    ListPrice              money            NOT NULL,
    Size                   nvarchar(5)      NULL,
    Weight                 decimal(8, 2)    NULL,
    ProductCategoryID      int              NULL,
    ProductModelID         int              NULL,
    SellStartDate          datetime         NOT NULL,
    SellEndDate            datetime         NULL,
    DiscontinuedDate       datetime         NULL,
    ThumbNailPhoto         varbinary(max)   NULL,
    ThumbnailPhotoFileName nvarchar(50)     NULL,
    rowguid                uniqueidentifier NOT NULL CONSTRAINT DF_Product_rowguid DEFAULT (NEWID()),
    ModifiedDate           datetime         NOT NULL CONSTRAINT DF_Product_ModifiedDate DEFAULT (GETDATE()),
    CONSTRAINT PK_Product_ProductID PRIMARY KEY CLUSTERED (ProductID),
    CONSTRAINT AK_Product_Name UNIQUE (Name),
    CONSTRAINT AK_Product_ProductNumber UNIQUE (ProductNumber),
    CONSTRAINT CK_Product_StandardCost CHECK (StandardCost >= 0.00),
    CONSTRAINT CK_Product_ListPrice CHECK (ListPrice >= 0.00),
    CONSTRAINT CK_Product_Weight CHECK (Weight > 0.00),
    CONSTRAINT CK_Product_SellEndDate CHECK (SellEndDate >= SellStartDate OR SellEndDate IS NULL),
    CONSTRAINT FK_Product_ProductCategory_ProductCategoryID
        FOREIGN KEY (ProductCategoryID) REFERENCES SalesLT.ProductCategory (ProductCategoryID),
    CONSTRAINT FK_Product_ProductModel_ProductModelID
        FOREIGN KEY (ProductModelID) REFERENCES SalesLT.ProductModel (ProductModelID)
);

CREATE TABLE SalesLT.SalesOrderHeader (
    SalesOrderID           int              NOT NULL,
    RevisionNumber         tinyint          NOT NULL CONSTRAINT DF_SalesOrderHeader_RevisionNumber DEFAULT (0),
    OrderDate              datetime         NOT NULL CONSTRAINT DF_SalesOrderHeader_OrderDate DEFAULT (GETDATE()),
    DueDate                datetime         NOT NULL,
    ShipDate               datetime         NULL,
    Status                 tinyint          NOT NULL CONSTRAINT DF_SalesOrderHeader_Status DEFAULT (1),
    OnlineOrderFlag        bit              NOT NULL CONSTRAINT DF_SalesOrderHeader_OnlineOrderFlag DEFAULT (1),
    SalesOrderNumber       AS (ISNULL(N'SO' + CONVERT(nvarchar(23), SalesOrderID), N'*** ERROR ***')),
    PurchaseOrderNumber    nvarchar(25)     NULL,
    AccountNumber          nvarchar(15)     NULL,
    CustomerID             int              NOT NULL,
    ShipToAddressID        int              NULL,
    BillToAddressID        int              NULL,
    ShipMethod             nvarchar(50)     NOT NULL,
    CreditCardApprovalCode varchar(15)      NULL,
    SubTotal               money            NOT NULL CONSTRAINT DF_SalesOrderHeader_SubTotal DEFAULT (0.00),
    TaxAmt                 money            NOT NULL CONSTRAINT DF_SalesOrderHeader_TaxAmt DEFAULT (0.00),
    Freight                money            NOT NULL CONSTRAINT DF_SalesOrderHeader_Freight DEFAULT (0.00),
    TotalDue               AS (ISNULL((SubTotal + TaxAmt) + Freight, (0))),
    Comment                nvarchar(max)    NULL,
    rowguid                uniqueidentifier NOT NULL CONSTRAINT DF_SalesOrderHeader_rowguid DEFAULT (NEWID()),
    ModifiedDate           datetime         NOT NULL CONSTRAINT DF_SalesOrderHeader_ModifiedDate DEFAULT (GETDATE()),
    CONSTRAINT PK_SalesOrderHeader_SalesOrderID PRIMARY KEY CLUSTERED (SalesOrderID),
    CONSTRAINT CK_SalesOrderHeader_Status CHECK (Status >= 0 AND Status <= 8),
    CONSTRAINT CK_SalesOrderHeader_DueDate CHECK (DueDate >= OrderDate),
    CONSTRAINT CK_SalesOrderHeader_ShipDate CHECK (ShipDate >= OrderDate OR ShipDate IS NULL),
    CONSTRAINT CK_SalesOrderHeader_SubTotal CHECK (SubTotal >= 0.00),
    CONSTRAINT CK_SalesOrderHeader_TaxAmt CHECK (TaxAmt >= 0.00),
    CONSTRAINT CK_SalesOrderHeader_Freight CHECK (Freight >= 0.00),
    CONSTRAINT FK_SalesOrderHeader_Customer_CustomerID
        FOREIGN KEY (CustomerID) REFERENCES SalesLT.Customer (CustomerID),
    CONSTRAINT FK_SalesOrderHeader_Address_ShipTo_AddressID
        FOREIGN KEY (ShipToAddressID) REFERENCES SalesLT.Address (AddressID),
    CONSTRAINT FK_SalesOrderHeader_Address_BillTo_AddressID
        FOREIGN KEY (BillToAddressID) REFERENCES SalesLT.Address (AddressID)
);

CREATE TABLE SalesLT.SalesOrderDetail (
    SalesOrderID       int              NOT NULL,
    SalesOrderDetailID int IDENTITY(1, 1) NOT NULL,
    OrderQty           smallint         NOT NULL,
    ProductID          int              NOT NULL,
    UnitPrice          money            NOT NULL,
    UnitPriceDiscount  money            NOT NULL CONSTRAINT DF_SalesOrderDetail_UnitPriceDiscount DEFAULT (0.0),
    LineTotal          AS (ISNULL((UnitPrice * ((1.0) - UnitPriceDiscount)) * OrderQty, (0.0))),
    rowguid            uniqueidentifier NOT NULL CONSTRAINT DF_SalesOrderDetail_rowguid DEFAULT (NEWID()),
    ModifiedDate       datetime         NOT NULL CONSTRAINT DF_SalesOrderDetail_ModifiedDate DEFAULT (GETDATE()),
    CONSTRAINT PK_SalesOrderDetail_SalesOrderID_SalesOrderDetailID PRIMARY KEY CLUSTERED (SalesOrderID, SalesOrderDetailID),
    CONSTRAINT CK_SalesOrderDetail_OrderQty CHECK (OrderQty > 0),
    CONSTRAINT CK_SalesOrderDetail_UnitPrice CHECK (UnitPrice >= 0.00),
    CONSTRAINT CK_SalesOrderDetail_UnitPriceDiscount CHECK (UnitPriceDiscount >= 0.00),
    CONSTRAINT FK_SalesOrderDetail_SalesOrderHeader_SalesOrderID
        FOREIGN KEY (SalesOrderID) REFERENCES SalesLT.SalesOrderHeader (SalesOrderID) ON DELETE CASCADE,
    CONSTRAINT FK_SalesOrderDetail_Product_ProductID
        FOREIGN KEY (ProductID) REFERENCES SalesLT.Product (ProductID)
);

/* Data */

/* SalesLT.Address: 450 rows */
SET IDENTITY_INSERT SalesLT.Address ON;
SET IDENTITY_INSERT SalesLT.Address OFF;

/* SalesLT.Customer: 847 rows */
SET IDENTITY_INSERT SalesLT.Customer ON;
SET IDENTITY_INSERT SalesLT.Customer OFF;

/* SalesLT.CustomerAddress: 417 rows */

/* SalesLT.ProductCategory: 41 rows */
SET IDENTITY_INSERT SalesLT.ProductCategory ON;
SET IDENTITY_INSERT SalesLT.ProductCategory OFF;

/* SalesLT.ProductModel: 128 rows */
SET IDENTITY_INSERT SalesLT.ProductModel ON;
SET IDENTITY_INSERT SalesLT.ProductModel OFF;

/* SalesLT.ProductDescription: 762 rows */
SET IDENTITY_INSERT SalesLT.ProductDescription ON;
SET IDENTITY_INSERT SalesLT.ProductDescription OFF;

/* SalesLT.ProductModelProductDescription: 762 rows */

/* SalesLT.Product: 295 rows */
SET IDENTITY_INSERT SalesLT.Product ON;
SET IDENTITY_INSERT SalesLT.Product OFF;

/* SalesLT.SalesOrderHeader: 32 rows */

/* SalesLT.SalesOrderDetail: 542 rows */
SET IDENTITY_INSERT SalesLT.SalesOrderDetail ON;
SET IDENTITY_INSERT SalesLT.SalesOrderDetail OFF;

COMMIT TRANSACTION;

/* Check: every line must say OK */
SELECT [check], actual, expected, CASE WHEN actual = expected THEN N'OK' ELSE N'CHECK THIS' END AS result
FROM (
    SELECT N'SalesLT.Address' AS [check], (SELECT COUNT_BIG(*) FROM SalesLT.Address) AS [actual], CAST(450 AS bigint) AS [expected]
    UNION ALL SELECT N'SalesLT.Customer' AS [check], (SELECT COUNT_BIG(*) FROM SalesLT.Customer) AS [actual], CAST(847 AS bigint) AS [expected]
    UNION ALL SELECT N'SalesLT.CustomerAddress' AS [check], (SELECT COUNT_BIG(*) FROM SalesLT.CustomerAddress) AS [actual], CAST(417 AS bigint) AS [expected]
    UNION ALL SELECT N'SalesLT.ProductCategory' AS [check], (SELECT COUNT_BIG(*) FROM SalesLT.ProductCategory) AS [actual], CAST(41 AS bigint) AS [expected]
    UNION ALL SELECT N'SalesLT.ProductModel' AS [check], (SELECT COUNT_BIG(*) FROM SalesLT.ProductModel) AS [actual], CAST(128 AS bigint) AS [expected]
    UNION ALL SELECT N'SalesLT.ProductDescription' AS [check], (SELECT COUNT_BIG(*) FROM SalesLT.ProductDescription) AS [actual], CAST(762 AS bigint) AS [expected]
    UNION ALL SELECT N'SalesLT.ProductModelProductDescription' AS [check], (SELECT COUNT_BIG(*) FROM SalesLT.ProductModelProductDescription) AS [actual], CAST(762 AS bigint) AS [expected]
    UNION ALL SELECT N'SalesLT.Product' AS [check], (SELECT COUNT_BIG(*) FROM SalesLT.Product) AS [actual], CAST(295 AS bigint) AS [expected]
    UNION ALL SELECT N'SalesLT.SalesOrderHeader' AS [check], (SELECT COUNT_BIG(*) FROM SalesLT.SalesOrderHeader) AS [actual], CAST(32 AS bigint) AS [expected]
    UNION ALL SELECT N'SalesLT.SalesOrderDetail' AS [check], (SELECT COUNT_BIG(*) FROM SalesLT.SalesOrderDetail) AS [actual], CAST(542 AS bigint) AS [expected]
    UNION ALL SELECT N'Products with no colour (quiz)' AS [check], (SELECT COUNT_BIG(*) FROM SalesLT.Product WHERE Color IS NULL) AS [actual], CAST(50 AS bigint) AS [expected]
    UNION ALL SELECT N'Red products (quiz)' AS [check], (SELECT COUNT_BIG(*) FROM SalesLT.Product WHERE Color = N'Red') AS [actual], CAST(38 AS bigint) AS [expected]
) AS c;
